# Examples

```
# use gpui::{Pixels, Point};
let p1 = Point { x: Pixels::from(1.0), y: Pixels::from(1.0) };
let p2 = Point { x: Pixels::from(3.0), y: Pixels::from(-2.0) };
assert_eq!(p1.is_nearly_eq(&p2, Pixels::from(4.0)), true);
```

